import { api, initLayout, toast, fmtDate, copyText } from '/js/layout.js';
import { highlightSQL } from '/js/sqlhighlight.js';

const list = document.querySelector('#saved-list');
const search = document.querySelector('#saved-search');
const titleEl = document.querySelector('#saved-title');
const sqlEl = document.querySelector('#saved-sql');
const sqlCode = document.querySelector('#saved-sql > code');
const resultEl = document.querySelector('#saved-result');
const tsvBtn = document.querySelector('#saved-tsv');
const openBtn = document.querySelector('#saved-open');
const deleteBtn = document.querySelector('#saved-delete');
let items = [];
let current = null;
let debounce = null;

async function loadList() {
  try {
    const page = await api('/api/v1/query/saved?limit=200');
    items = page.items || [];
    renderList();
  } catch (cause) { list.className = 'empty'; list.textContent = cause.message; }
}

function renderList() {
  const term = search.value.trim().toLowerCase();
  const filtered = items.filter((s) => !term || (s.sql || '').toLowerCase().includes(term) || (s.db_name || '').toLowerCase().includes(term));
  document.querySelector('#saved-count').textContent = `${filtered.length}건`;
  if (!filtered.length) { list.className = 'empty'; list.textContent = '저장된 결과가 없습니다.'; return; }
  list.className = 'resource-list';
  list.replaceChildren(...filtered.map((s) => {
    const btn = document.createElement('button');
    btn.type = 'button'; btn.className = 'resource-card' + (current && current.id === s.id ? ' active' : '');
    const top = document.createElement('div'); top.className = 'rc-top';
    const name = document.createElement('strong'); name.textContent = `#${s.id} · ${s.db_name || 'DB#' + s.db_seq}`;
    top.append(name);
    const meta = document.createElement('span'); meta.className = 'rc-meta'; meta.textContent = `${s.row_count}행 · ${s.user_name || ''} · ${fmtDate(s.created_at)}`;
    const desc = document.createElement('span'); desc.className = 'rc-desc'; desc.textContent = s.sql;
    btn.append(top, meta, desc);
    btn.addEventListener('click', () => { list.querySelectorAll('.resource-card.active').forEach((c) => c.classList.remove('active')); btn.classList.add('active'); showDetail(s.id); });
    return btn;
  }));
}

async function showDetail(id) {
  titleEl.textContent = `결과 #${id} 불러오는 중...`;
  try {
    const d = await api(`/api/v1/query/saved/${id}`);
    current = d;
    titleEl.textContent = `결과 #${d.id} · ${d.db_name || 'DB#' + d.db_seq} · ${d.row_count}행`;
    sqlEl.hidden = false; sqlCode.innerHTML = highlightSQL(d.sql || '');
    tsvBtn.hidden = false; openBtn.hidden = false; deleteBtn.hidden = false;
    renderResult(d);
  } catch (cause) { resultEl.className = 'empty'; resultEl.textContent = cause.message; }
}

function renderResult(d) {
  if (!d.columns || !d.columns.length) { resultEl.className = 'empty'; resultEl.textContent = '저장된 컬럼이 없습니다.'; return; }
  resultEl.className = 'query-grid-wrap';
  const table = document.createElement('table');
  const head = document.createElement('thead'); const hr = document.createElement('tr');
  const idxTh = document.createElement('th'); idxTh.className = 'row-idx'; idxTh.textContent = '#'; hr.append(idxTh);
  d.columns.forEach((c) => { const th = document.createElement('th'); th.textContent = c.name; th.title = c.type; hr.append(th); });
  head.append(hr);
  const body = document.createElement('tbody');
  (d.rows || []).forEach((row, i) => {
    const tr = document.createElement('tr');
    const idx = document.createElement('td'); idx.className = 'row-idx'; idx.textContent = String(i + 1); tr.append(idx);
    d.columns.forEach((c) => { const td = document.createElement('td'); const v = row[c.name]; if (v === null || v === undefined) { td.textContent = 'NULL'; td.className = 'null-value'; } else td.textContent = String(v); tr.append(td); });
    body.append(tr);
  });
  table.append(head, body);
  resultEl.replaceChildren(table);
}

tsvBtn.addEventListener('click', () => {
  if (!current) return;
  const cols = current.columns.map((c) => c.name);
  const lines = [cols.join('\t'), ...(current.rows || []).map((r) => cols.map((c) => { const v = r[c]; return v == null ? '' : String(v).replace(/[\t\n\r]/g, ' '); }).join('\t'))];
  copyText(lines.join('\n'), 'TSV로 복사했습니다.');
});
openBtn.addEventListener('click', () => {
  if (!current) return;
  sessionStorage.setItem('dartfly.pendingSQL', current.sql || '');
  if (current.db_seq) sessionStorage.setItem('dartfly.pendingDB', String(current.db_seq));
  window.location.href = '/';
});
deleteBtn.addEventListener('click', async () => {
  if (!current || !window.confirm(`저장 결과 #${current.id}을(를) 삭제할까요?`)) return;
  try {
    await api(`/api/v1/query/saved/${current.id}`, { method: 'DELETE' });
    toast('삭제했습니다.');
    current = null; sqlEl.hidden = true; tsvBtn.hidden = openBtn.hidden = deleteBtn.hidden = true;
    titleEl.textContent = '결과를 선택하세요'; resultEl.className = 'empty'; resultEl.textContent = '-';
    await loadList();
  } catch (cause) { toast(cause.message, true); }
});
search.addEventListener('input', () => { clearTimeout(debounce); debounce = setTimeout(renderList, 200); });

initLayout('/saved').then(loadList).catch((cause) => { list.className = 'empty'; list.textContent = cause.message; });
