// 브라우저용 모듈을 Node 에서 불러오는 공용 로더.
//
// 화면 모듈은 '/js/foo.js' 처럼 브라우저 절대 경로로 서로를 참조합니다. Node 는 그
// 경로를 해석하지 못하므로 파일 URL 로 바꿔 읽습니다. 모듈이 서로를 참조하기
// 시작하면 테스트마다 같은 처리를 하게 되므로 한 곳에 둡니다.
import { readFileSync } from 'node:fs';

const REPO = new URL('../../', import.meta.url);
const ROOT = new URL('internal/webui/js/', REPO);

// repoFile: 저장소 기준 경로를 현재 작업 디렉터리와 무관하게 읽습니다.
//
// 예전에는 테스트들이 readFileSync('internal/webui/js/app.js') 처럼 상대 경로를
// 썼습니다. 저장소 최상위에서 실행할 때만 통했고, 다른 곳에서 부르면 ENOENT 로
// 죽었습니다.
export function repoFile(path) {
  return readFileSync(new URL(path, REPO), 'utf8');
}

export async function loadModule(name) {
  const source = readFileSync(new URL(name, ROOT), 'utf8')
    .replaceAll(/from '\/js\/([\w.-]+)'/g, (_, dep) => `from '${new URL(dep, ROOT).href}'`);
  return import('data:text/javascript;base64,' + Buffer.from(source).toString('base64'));
}
